import {
    type Source,
    Record,
    type Factory as IFactory,
    Shape,
    type Action,
    RecordId,
    type InstallCategory,
    getInstallCategory,
    isGUID,
    StringShape,
    NumberShape,
    type CoalesceKeys,
    ObjectShape,
    UndefinedShape,
    GUID,
} from '@servicenow/sdk-build-core'
import type { Project } from '../project'
import { NowIdShape } from '@servicenow/sdk-build-plugins'

export class Factory implements IFactory {
    constructor(private readonly project: Project) {}

    async createShape<const S extends Shape>(shape: S): Promise<S> {
        const result = await this.project.getTransform().toSubclass(shape)
        return result.success ? result.value : shape
    }

    async createRecord({
        source,
        explicitId: rawExplicitId,
        table,
        properties: rawProperties,
        action = 'INSERT_OR_UPDATE',
        installCategory = getInstallCategory(source, table),
    }: {
        source: Source
        explicitId?: string | number | Shape
        table: string
        properties: NonNullable<object>
        action?: Action
        installCategory?: InstallCategory
    }): Promise<Record> {
        const registry = this.project.getKeys()
        const propertiesShape = Shape.from(source, rawProperties).asObject()
        const sysId = propertiesShape.get('sys_id').ifString()?.getValue()
        const properties = propertiesShape.omit('sys_id')

        const explicitId =
            rawExplicitId instanceof Shape
                ? rawExplicitId.as([NowIdShape, StringShape, NumberShape, UndefinedShape]).getValue()
                : rawExplicitId

        // If the explicit ID is already a GUID, we treat that as the GUID instead of generating
        // one. If not, we'll use the sys_id property if it exists. This is to ensure we preserve
        // existing GUIDs as much as possible, as well as to stay compatible with code that might
        // still have hard-coded GUIDs in it, like the default view.
        const guidOverride = typeof explicitId === 'string' && isGUID(explicitId) ? explicitId : sysId

        // We'll avoid registering keys if the record is being deleted, because either it exists
        // in the code already and is therefore already registered, or it's never going to exist
        const isDelete = Record.isDeleteAction(action)

        // TODO: We are checking for a coalesce strategy even when an explicit ID is passed in
        //  because the Record API has a mandatory $id property and RecordPlugin doesn't know
        //  if the record has a coalesce strategy or not, so it always passes it in. We should
        //  make the $id property optional in the Record API and have RecordPlugin only pass it
        //  in if it's present, that way we can avoid the need to always check for a coalesce
        //  strategy first.
        const coalesceStrategy = this.project.getPlugins().getCoalesceStrategy(table)
        if (coalesceStrategy) {
            let coalesceKeys: CoalesceKeys
            if (Array.isArray(coalesceStrategy)) {
                coalesceKeys = Object.fromEntries(
                    coalesceStrategy.map((k) => [
                        k,
                        propertiesShape
                            .get(k)
                            .pipe(
                                (v) => v.ifRecordId() ?? v.ifRecord()?.getId() ?? v.ifDefined()?.toString().getValue()
                            ) || 'NULL',
                    ])
                )
            } else {
                const dynamicKeys = coalesceStrategy(propertiesShape)
                const entries = dynamicKeys instanceof ObjectShape ? dynamicKeys.entries() : Object.entries(dynamicKeys)

                coalesceKeys = Object.fromEntries(
                    entries.map(([k, v]) => [
                        k,
                        typeof v === 'string' ? v : v.asString('Dynamic coalesce value must be a string').getValue(),
                    ])
                )
            }

            const actualOverride = explicitId
                ? (registry.queryExplicitId(table, explicitId) ?? guidOverride)
                : guidOverride

            return this.createShape(
                new Record({
                    source,
                    properties,
                    action,
                    installCategory,
                    id: await this.createShape(
                        new RecordId({
                            source,
                            table,
                            nowIdKey: explicitId,
                            keys: coalesceKeys,
                            guid: isDelete
                                ? registry.deleteCoalesceId(table, coalesceKeys, actualOverride)
                                : registry.registerCoalesceId(table, coalesceKeys, actualOverride),
                        })
                    ),
                })
            )
        }

        // An ID was explicitly provided in the code, so we'll register it to get a usable GUID.
        if (explicitId) {
            return this.createShape(
                new Record({
                    source,
                    properties,
                    action,
                    installCategory,
                    id: await this.createShape(
                        new RecordId({
                            source,
                            table,
                            nowIdKey: explicitId,
                            guid: isDelete
                                ? registry.deleteExplicitId(table, explicitId, guidOverride)
                                : registry.registerExplicitId(table, explicitId, guidOverride),
                        })
                    ),
                })
            )
        }

        // At this point, our last resort is to use the sys_id property as-is.
        if (sysId) {
            return this.createShape(
                new Record({
                    source,
                    properties,
                    action,
                    installCategory,
                    id: await this.createShape(
                        new RecordId({
                            source,
                            table,
                            guid: isDelete ? registry.deleteExplicitId(table, sysId, sysId) : sysId,
                        })
                    ),
                })
            )
        }

        throw new Error(
            `Failed to determine ID for "${table}" record. No ID was provided, no coalesce strategy was found, and no sys_id was defined in the record's properties.`
        )
    }

    async createReference({
        source,
        table: rawTable,
        guid: rawGuid,
        keys: rawKeys,
    }: {
        source: Source
        table: string | StringShape
        guid?: string | StringShape | undefined
        keys?: globalThis.Record<string, string | Shape> | ObjectShape | undefined
    }): Promise<RecordId> {
        const table = typeof rawTable === 'string' ? rawTable : rawTable.getValue()
        if (!rawGuid && !rawKeys) {
            throw new Error(`Failed to create "${table}" reference. No GUID or coalesce keys were provided.`)
        }

        const guid = typeof rawGuid === 'string' ? rawGuid : rawGuid?.getValue()
        const keys = rawKeys
            ? Object.fromEntries(
                  (rawKeys instanceof ObjectShape ? rawKeys.entries() : Object.entries(rawKeys)).map(([k, v]) => [
                      k,
                      typeof v === 'string'
                          ? v
                          : (v.ifRecord()?.getId() ?? v.ifRecordId() ?? v.ifDefined()?.toString().getValue()) || 'NULL',
                  ])
              )
            : undefined

        return this.createShape(
            new RecordId({
                source,
                table,
                keys,
                guid: () => {
                    // TODO: Is a random GUID as a last resort the right thing to do here? Usually this will happen
                    //  for coalescing references that came from the instance which we wrote to the code without the
                    //  original sys ID, such as when we write user roles as just the role name. When we go to resolve
                    //  the reference, there will be no key registered for that role, even though we did actually have
                    //  the sys ID when we originally brought down the reference. Maybe we can have something similar
                    //  to the keys registry but for storing "known" sys IDs for references to external stuff.
                    // Defer NowIdShape resolution so referenced entities have time to register

                    const fallback = guid
                        ? isGUID(guid)
                            ? guid
                            : (this.project.getKeys().queryExplicitId(table, guid) ?? guid)
                        : GUID()

                    return keys ? (this.project.getKeys().queryCoalesceId(table, keys) ?? fallback) : fallback
                },
            })
        )
    }
}
